def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    # Count recent opponent behavior in several windows
    last1 = opp(n - 1)
    last2 = opp(n - 2)
    last3 = opp(n - 3)
    last4 = opp(n - 4)
    last5 = opp(n - 5)
    last6 = opp(n - 6)
    last7 = opp(n - 7)
    last8 = opp(n - 8)
    last9 = opp(n - 9)
    last10 = opp(n - 10)

    def count_d(start, end):
        c = 0
        for i in range(start, end):
            if opp(i) == 'D':
                c += 1
        return c

    # Establish whether opponent is mostly cooperative / exploitative.
    d10 = count_d(n - 10, n)
    d20 = count_d(n - 20, n) if n >= 20 else count_d(0, n)

    # Exploit highly cooperative opponents aggressively but not immediately.
    if d10 == 0 and n >= 8:
        # If opponent never defected last 10, try to get 5-point gains.
        # But avoid too predictable: defect on alternate or every third when safe.
        # Against always-C this yields 5s; against delayed punishers it recovers.
        if n % 3 == 0:
            return 'D'
        return 'C'

    # If opponent has shown persistent defection, punish.
    if d10 >= 6:
        # Strong punishment: defect frequently, occasionally test C.
        if n % 5 == 0:
            return 'C'
        return 'D'

    # If opponent has defected moderately, use tit-for-tat with occasional forgiveness.
    if d10 >= 3:
        if last1 == 'D':
            # Forgive if opponent cooperated after our last D or if long time since last D.
            if last2 == 'C' and last3 == 'C':
                return 'C'
            if n % 7 == 0:
                return 'C'
            return 'D'
        else:
            # Opponent just cooperated. Keep cooperating unless signal suggests trap.
            if last2 == 'D' and last3 == 'D' and last4 == 'D':
                return 'D'
            return 'C'

    # Otherwise mostly cooperate, with occasional probing and retaliation.
    # Detect patterns of defection after our cooperation.
    cd = 0
    dc = 0
    for i in range(1, n):
        if me(i - 1) == 'C' and opp(i) == 'D':
            cd += 1
        if me(i - 1) == 'D' and opp(i) == 'C':
            dc += 1

    # If opponent often defects after our C, become cautious.
    if cd >= 3 and cd > dc:
        if last1 == 'D':
            return 'D'
        if n % 4 == 0:
            return 'D'
        return 'C'

    # Default: cooperate, but occasionally defect to test for exploitability.
    # Avoid testing too early or too late.
    if n >= 12 and n % 13 == 0:
        return 'D'

    return 'C'
